-- =======================================================================
-- 0001_schema_core.sql
-- =======================================================================
-- 0001_schema_core.sql
-- Platform v2 core schema: enum types, profiles, admin bootstrap list, and the
-- catalog tables (products, quizzes, pack_quizzes, questions).
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline,
-- the questions lockdown, and every policy live in the 0005-0010 migrations.
-- Triggers and helper functions live in 0003.
--
-- Requirements: 3.3, 9.8, 26.1, 27.11, 35.1, 35.2, 35.3

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Enum types
-- ---------------------------------------------------------------------------
-- Statuses are enums rather than text-with-check so an invalid value cannot be
-- written even by the service role.

create type product_type      as enum ('material', 'quiz_pack');
create type order_status      as enum ('pending', 'paid', 'failed', 'refunded');
create type enrollment_source as enum ('purchase', 'comp', 'credit');
create type referral_status   as enum ('available', 'paid', 'void');
create type reward_type       as enum ('cash', 'credit');
create type incident_kind     as enum ('amount_mismatch', 'currency_mismatch',
                                       'unmatched_payment', 'unmatched_refund',
                                       'out_of_order_status', 'self_referral');

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
-- One row per auth.users row, inserted by the on_auth_user_created trigger
-- (migration 0003). Requirement 3.3: ref_code uniqueness is a constraint, not a
-- convention.

create table public.profiles (
  id           uuid primary key references auth.users(id) on delete cascade,
  email        text not null,
  display_name text,
  is_admin     boolean not null default false,
  ref_code     text not null unique,
  referred_by  text references public.profiles(ref_code),
  gcash_number text,
  created_at   timestamptz not null default now()
);

comment on column public.profiles.is_admin is
  'Set by handle_new_user() from admin_bootstrap_emails. Never writable by a client role: see the column-level update grant and guard_profile_columns().';

-- ---------------------------------------------------------------------------
-- admin_bootstrap_emails
-- ---------------------------------------------------------------------------
-- Requirement 26.1. Admin bootstrap is data, not a hardcoded list inside the
-- trigger, so appointing an admin before their first login is a service-role
-- insert rather than a migration edit. Service-role only: no grants, no
-- policies (migrations 0005 and 0009).

create table public.admin_bootstrap_emails (
  email text primary key
);

insert into public.admin_bootstrap_emails (email)
values ('rehinaneel@gmail.com'), ('nairutya.84@gmail.com'), ('nairutya.iitp@gmail.com')
on conflict (email) do nothing;

-- Requirement 26.1 for profiles that already exist when this migration runs.
-- A no-op on a fresh database; the trigger in 0003 covers rows created later.
update public.profiles p
set is_admin = true
where exists (
  select 1 from public.admin_bootstrap_emails b
  where b.email = lower(p.email)
) and p.is_admin = false;

-- ---------------------------------------------------------------------------
-- products
-- ---------------------------------------------------------------------------
-- Requirement 27.11: price_php is a positive integer, slug is unique, and type
-- is constrained by the enum, so an invalid product save fails at the database
-- even if the Admin_Function validation is bypassed.
-- Requirement 35.1: the seed import maps v1 'material'/'quiz' onto
-- 'material'/'quiz_pack' and preserves title, subject, description, price, and
-- sort order.
-- material_path is never granted to a client role (migration 0008);
-- thumbnail_path is, because thumbnails live in a separate public bucket.

create table public.products (
  id             uuid primary key default gen_random_uuid(),
  slug           text not null unique,
  type           product_type not null,
  subject        text,
  title          text not null,
  subtitle       text,
  description    text,
  price_php      integer not null check (price_php > 0),
  currency       char(3) not null default 'PHP' check (currency = 'PHP'),
  thumbnail_path text,
  material_path  text,
  includes       jsonb not null default '[]'::jsonb,
  published      boolean not null default false,
  sort_order     integer not null default 0,
  created_at     timestamptz not null default now()
);

comment on column public.products.material_path is
  'Object path in the private Materials_Bucket. Withheld from the anon/authenticated select grant so the browser never learns the object layout.';

-- Supports the published-only catalog read ordered by sort_order.
create index products_published_sort_idx on public.products (published, sort_order);

-- ---------------------------------------------------------------------------
-- quizzes
-- ---------------------------------------------------------------------------
-- Requirement 9.8: metadata only. Question content lives in public.questions,
-- which no client role can reach at all.
-- Requirement 35.2: one row per distinct v1 quiz_id, preserving title, subject,
-- and timer_minutes.

create table public.quizzes (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,
  title         text not null,
  subject       text,
  timer_minutes integer not null default 0 check (timer_minutes >= 0),
  published     boolean not null default false,
  created_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- pack_quizzes
-- ---------------------------------------------------------------------------
-- Maps quiz-pack products to the quizzes they unlock. Visibility follows the
-- parent product's published flag (policy in migration 0008).

create table public.pack_quizzes (
  product_id uuid not null references public.products(id) on delete cascade,
  quiz_id    uuid not null references public.quizzes(id) on delete cascade,
  sort_order integer not null default 0,
  primary key (product_id, quiz_id)
);

-- ---------------------------------------------------------------------------
-- questions
-- ---------------------------------------------------------------------------
-- Requirement 35.3: one row per v1 question, preserving text, options, the
-- correct option as correct_key, and the explanation.
-- The answer-key guarantee (Requirement 6) is enforced in migration 0006 by
-- granting nothing to anon/authenticated and defining zero policies. Do not add
-- a client grant or policy here.

create table public.questions (
  id              uuid primary key default gen_random_uuid(),
  quiz_id         uuid not null references public.quizzes(id) on delete cascade,
  question_number integer not null,
  question_text   text not null,
  options         jsonb not null,
  correct_key     text not null,
  explanation     text,
  created_at      timestamptz not null default now(),
  unique (quiz_id, question_number)
);

comment on table public.questions is
  'Answer keys. Reachable only by service_role. No anon/authenticated grant and no RLS policy may ever be added: see migration 0006.';

-- =======================================================================
-- 0002_schema_money.sql
-- =======================================================================
-- 0002_schema_money.sql
-- Platform v2 money and access schema: orders, enrollments, quiz_attempts,
-- referrals, payment_incidents, payout_requests.
--
-- Depends on 0001_schema_core.sql for pgcrypto, the enum types
-- (order_status, enrollment_source, referral_status, reward_type,
-- incident_kind) and the profiles/products/quizzes tables. Those types are
-- reused here, never redeclared.
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline
-- and every policy live in the 0005-0010 migrations; fulfil_payment,
-- refund_payment and fail_payment live in 0011-0012.
--
-- Requirements: 16.1, 15.8, 25.7

-- ---------------------------------------------------------------------------
-- orders
-- ---------------------------------------------------------------------------
-- amount_php is numeric(12,2), not integer: HitPay reports decimal amounts and
-- Requirement 15.1 compares at 2-decimal-place precision, so the stored value
-- has to hold two decimals to be comparable with zero tolerance. The integer
-- products.price_php widens losslessly into it (Requirement 15.5: the compared
-- value comes from the database, never from the payload).
--
-- on delete restrict on both references: an order is a financial record, so
-- deleting a buyer or a product must not silently erase it.
--
-- currency carries no check constraint here, matching the design. Orders record
-- what was charged, and Requirement 15.2 compares the reported currency against
-- this stored value at webhook time rather than constraining it at write time.

create table public.orders (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references public.profiles(id) on delete restrict,
  product_id        uuid not null references public.products(id) on delete restrict,
  amount_php        numeric(12,2) not null check (amount_php > 0),
  currency          char(3) not null default 'PHP',
  status            order_status not null default 'pending',
  hitpay_payment_id text,
  hitpay_reference  text,
  ref_code          text,
  created_at        timestamptz not null default now(),
  paid_at           timestamptz
);

comment on column public.orders.amount_php is
  'Written by the Create_Payment_Function from products.price_php at order creation. Requirement 15.5: no part of the webhook cross-check value may come from the payload.';

-- Requirement 16.1: unique over non-null payment ids only, so many pending
-- orders may coexist before HitPay assigns an id. A plain unique constraint
-- would work in Postgres (nulls are distinct) but a partial index states the
-- intent and keeps the index off the pending rows.
create unique index orders_hitpay_payment_id_key
  on public.orders (hitpay_payment_id)
  where hitpay_payment_id is not null;

-- Supports the buyer's own order history and the enrolled-confirmation poll.
create index orders_user_idx on public.orders (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- enrollments
-- ---------------------------------------------------------------------------
-- Requirement 16.1: unique (user_id, product_id) is what makes replayed
-- fulfilment idempotent at the database level, so `on conflict do nothing` in
-- fulfil_payment is a guarantee rather than a hope.
--
-- Revoking an enrollment deletes the row (design decision), which keeps this a
-- plain constraint rather than a partial index and lets a refunded buyer
-- purchase the same product again later.
--
-- order_id is nullable with on delete set null: comp and credit enrollments
-- have no order behind them.

create table public.enrollments (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  source     enrollment_source not null,
  order_id   uuid references public.orders(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint enrollments_user_product_key unique (user_id, product_id)
);

comment on constraint enrollments_user_product_key on public.enrollments is
  'Requirement 16.1. Database-level idempotency for fulfilment: at most one enrollment per user per product, however many times a webhook is replayed.';

-- ---------------------------------------------------------------------------
-- quiz_attempts
-- ---------------------------------------------------------------------------
-- score and total are computed by grade-quiz from questions.correct_key with
-- the service role; any score, total, or correctness field in the request body
-- is ignored. Requirement 17.2 preserves these rows across a refund.

create table public.quiz_attempts (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles(id) on delete cascade,
  quiz_id    uuid not null references public.quizzes(id) on delete cascade,
  score      integer not null check (score >= 0),
  total      integer not null check (total >= 0),
  answers    jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- referrals
-- ---------------------------------------------------------------------------
-- Requirement 16.1: unique order_id is the exactly-once guarantee for referral
-- attribution under webhook replay.
--
-- buyer_masked is computed once by the service role at insert time
-- (juan****@gmail.com) so buyer_user_id can be withheld from the client grant
-- entirely (migration 0009) and the referrer never receives the buyer's
-- identity. product_title is denormalised so the ledger still renders after the
-- product is unpublished and therefore invisible to the referrer's catalog read.
--
-- referrals_no_self makes the self-referral guard a database invariant, not
-- only a branch in the webhook.
--
-- amount_php allows 0 (>= 0) because a credit-mode or zero-configured reward is
-- still a valid ledger row; orders.amount_php stays strictly positive.

create table public.referrals (
  id                uuid primary key default gen_random_uuid(),
  referrer_ref_code text not null,
  referrer_user_id  uuid not null references public.profiles(id) on delete cascade,
  buyer_user_id     uuid not null references public.profiles(id) on delete cascade,
  buyer_masked      text not null,
  order_id          uuid not null unique references public.orders(id) on delete cascade,
  product_id        uuid not null references public.products(id) on delete restrict,
  product_title     text not null,
  amount_php        numeric(12,2) not null check (amount_php >= 0),
  reward_type       reward_type not null,
  status            referral_status not null default 'available',
  created_at        timestamptz not null default now(),
  paid_at           timestamptz,
  notes             text,
  constraint referrals_no_self check (referrer_user_id <> buyer_user_id)
);

comment on column public.referrals.buyer_user_id is
  'Service-role only. Withheld from the column-level select grant in migration 0009; the ledger renders buyer_masked instead.';

-- Supports the earnings dashboard: available and paid balances per referrer.
create index referrals_referrer_idx on public.referrals (referrer_user_id, status);

-- ---------------------------------------------------------------------------
-- payment_incidents
-- ---------------------------------------------------------------------------
-- Requirement 15.8: the store behind every "record for admin review" clause.
-- Retains the reported amount, reported currency, reported payment identifier,
-- the stored amount and currency, and the recording time, associated with the
-- matching order where one exists, until an admin marks it resolved.
--
-- order_id is nullable: unmatched payments and unmatched refunds have no order
-- to point at, which is precisely why they are incidents.
--
-- payload holds the webhook body for forensics and can contain payer details,
-- so this table gets zero grants and zero policies (migrations 0005 and 0009);
-- the admin portal reads it through admin-incidents, never through PostgREST.

create table public.payment_incidents (
  id                uuid primary key default gen_random_uuid(),
  kind              incident_kind not null,
  order_id          uuid references public.orders(id) on delete set null,
  hitpay_payment_id text,
  reported_amount   numeric(12,2),
  reported_currency text,
  stored_amount     numeric(12,2),
  stored_currency   char(3),
  payload           jsonb,
  resolved_at       timestamptz,
  resolved_by       uuid references public.profiles(id),
  created_at        timestamptz not null default now()
);

comment on table public.payment_incidents is
  'Requirement 15.8. Service-role only: payload may contain payer details. No anon/authenticated grant and no policy may be added.';

-- Supports the admin review list: unresolved incidents, newest first, paged at 50.
create index payment_incidents_open_idx
  on public.payment_incidents (created_at desc) where resolved_at is null;

-- ---------------------------------------------------------------------------
-- payout_requests
-- ---------------------------------------------------------------------------
-- Requirement 25.7: request-payout recomputes the available balance from
-- referrals server-side and inserts exactly one row here with the supplied
-- GCash number. amount_php > 0 so a zero-balance request cannot be recorded.
-- status is text-with-check rather than an enum because it is a workflow label
-- the admin portal owns, not a value any money path branches on.

create table public.payout_requests (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles(id) on delete cascade,
  amount_php   numeric(12,2) not null check (amount_php > 0),
  gcash_number text not null,
  status       text not null default 'requested'
               check (status in ('requested','paid','rejected')),
  created_at   timestamptz not null default now(),
  handled_at   timestamptz,
  notes        text
);

-- =======================================================================
-- 0003_functions_triggers.sql
-- =======================================================================
-- 0003_functions_triggers.sql
-- Platform v2 provisioning functions and triggers:
--   gen_ref_code()          unambiguous referral code with collision retry
--   handle_new_user()       one profiles row per auth.users row, admin bootstrap
--   on_auth_user_created    the auth.users trigger that calls it
--   mask_email()            buyer mask stored on referrals.buyer_masked
--   guard_profile_columns() + profiles_guard_columns trigger
--
-- Depends on 0001_schema_core.sql for public.profiles and
-- public.admin_bootstrap_emails.
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline
-- (migration 0005) revokes execute on every function in schema public from
-- anon and authenticated; none of the functions here needs a client grant,
-- because Postgres checks EXECUTE on a trigger function when the trigger is
-- created, not each time it fires. mask_email() is called by the service role
-- from inside fulfil_payment (migration 0011), which is SECURITY DEFINER.
--
-- Requirements: 3.1, 3.2, 3.4, 9.2, 9.3, 26.2, 7.7

-- ---------------------------------------------------------------------------
-- gen_ref_code
-- ---------------------------------------------------------------------------
-- Requirement 3.2: ref_code is unique across profiles.
-- Requirement 3.4: on collision the function generates a replacement and the
-- insert completes, so uniqueness does not depend on the constraint raising.
--
-- The alphabet omits I, O, 0 and 1 so a code survives being read aloud or
-- hand-typed. 32 symbols over 8 positions is ~1.1e12 codes, so the retry loop
-- is a correctness guarantee rather than a hot path.

create or replace function public.gen_ref_code() returns text
language plpgsql
set search_path = public, pg_temp
as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  candidate text;
begin
  loop
    candidate := '';
    for i in 1..8 loop
      candidate := candidate
        || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (
      select 1 from public.profiles where ref_code = candidate
    );
  end loop;
  return candidate;
end $$;

comment on function public.gen_ref_code() is
  'Requirement 3.4. Generates an 8-character referral code over the unambiguous alphabet and retries until it does not collide with an existing profiles.ref_code.';

-- ---------------------------------------------------------------------------
-- handle_new_user
-- ---------------------------------------------------------------------------
-- Requirement 3.1: one profiles row per auth.users insert, by way of a trigger.
-- Requirement 3.2: email copied from auth.users, ref_code unique.
-- Requirement 26.2: is_admin is true exactly when the address is in
-- admin_bootstrap_emails, which is data rather than a list inside this body, so
-- appointing an admin before their first login is a service-role insert.
--
-- SECURITY DEFINER because the trigger fires as the auth admin role, which has
-- no privilege on public.profiles. search_path is pinned so a definer function
-- cannot be redirected at a shadowed table by the caller's search_path.
--
-- Bootstrap addresses are stored lower-case in 0001, so the comparison
-- lower-cases the incoming address rather than trusting its case.
--
-- on conflict (id) do nothing keeps a re-inserted or replayed auth row from
-- raising, which would otherwise fail the signup itself.

create or replace function public.handle_new_user() returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, email, ref_code, is_admin)
  values (
    new.id,
    new.email,
    public.gen_ref_code(),
    exists (
      select 1 from public.admin_bootstrap_emails
      where email = lower(new.email)
    )
  )
  on conflict (id) do nothing;
  return new;
end $$;

comment on function public.handle_new_user() is
  'Requirements 3.1, 3.2, 26.2. Inserts the profiles row for a new auth.users row and sets is_admin from admin_bootstrap_emails.';

-- No drop-if-exists guard here: auth.users is owned by the auth admin role, and
-- DROP TRIGGER requires ownership of the table while CREATE TRIGGER needs only
-- the TRIGGER privilege. The migration ledger applies this file once.

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- mask_email
-- ---------------------------------------------------------------------------
-- Requirement 7.7: the referrer sees the buyer in masked form. The mask is
-- computed once by the service role at insert time and stored in
-- referrals.buyer_masked, so buyer_user_id can be withheld from the client
-- grant entirely (migration 0009) and the raw identity never reaches the
-- browser at all.
--
-- Shape, per the design: up to the first four characters of the local part,
-- four mask characters, then the domain -> juan****@gmail.com with U+2022
-- bullets. The bullets are produced with chr(8226) so this file stays pure
-- ASCII and cannot be corrupted by a re-encode; the value stored is the bullet
-- character itself. A local part shorter than four characters is shown in full,
-- which is the same amount of information the mask shape already implies.
--
-- Anything that is not recognisably an address (null, blank, no '@', nothing
-- before the '@', nothing after it) masks to '***' rather than to null, because
-- referrals.buyer_masked is not null.

create or replace function public.mask_email(p_email text) returns text
language plpgsql
immutable
as $$
declare
  v_input  text := btrim(coalesce(p_email, ''));
  v_at     int;
  v_local  text;
  v_domain text;
begin
  v_at := position('@' in v_input);
  if v_at < 2 then
    return '***';
  end if;

  v_local  := left(v_input, v_at - 1);
  v_domain := substr(v_input, v_at + 1);

  if v_domain = '' then
    return '***';
  end if;

  return left(v_local, 4) || repeat(chr(8226), 4) || '@' || v_domain;
end $$;

comment on function public.mask_email(text) is
  'Requirement 7.7. Buyer mask stored on referrals.buyer_masked: up to four characters of the local part, four bullet characters, then the domain.';

-- ---------------------------------------------------------------------------
-- guard_profile_columns
-- ---------------------------------------------------------------------------
-- Requirements 9.2 and 9.3 are enforced first by the column-level update grant
-- in migration 0007, which permits display_name and gcash_number only. An
-- attempt to set is_admin is rejected with "permission denied for column
-- is_admin" before any policy runs.
--
-- This trigger is defence in depth behind that grant: if the grant were ever
-- widened, a client-side update of is_admin, ref_code, referred_by, email or id
-- would still be rejected, here with SQLSTATE 42501 (insufficient_privilege) so
-- the client sees the same class of error either way.
--
-- The guard applies only when a request carries a user identity. auth.uid() is
-- null for the service role, so fulfil_payment, refund_payment and the admin
-- functions can still maintain these columns; the role check is a second
-- shortcut for the same case. Comparisons use IS DISTINCT FROM so a null-to-null
-- no-op update is not mistaken for a change.

create or replace function public.guard_profile_columns() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is not null and current_setting('role') <> 'service_role' then
    if new.is_admin    is distinct from old.is_admin
    or new.ref_code    is distinct from old.ref_code
    or new.referred_by is distinct from old.referred_by
    or new.email       is distinct from old.email
    or new.id          is distinct from old.id then
      raise exception 'protected profile column' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

comment on function public.guard_profile_columns() is
  'Requirements 9.2, 9.3. Defence in depth behind the column-level update grant on profiles: blocks a user-identified update of is_admin, ref_code, referred_by, email or id.';

drop trigger if exists profiles_guard_columns on public.profiles;

create trigger profiles_guard_columns
before update on public.profiles
for each row execute function public.guard_profile_columns();

-- =======================================================================
-- 0004_settings_seed.sql
-- =======================================================================
-- 0004_settings_seed.sql
-- Platform v2 settings: the key/value configuration table and its seeded rows.
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline is
-- migration 0005 and the display-safe allowlist policy
-- (settings_select_display_safe) is migration 0010. This file depends only on
-- the public schema, so it is independent of 0002 and 0003.
--
-- Requirements: 20.12, 24.1, 9.9

-- ---------------------------------------------------------------------------
-- settings
-- ---------------------------------------------------------------------------
-- value is text for every key. Numeric and enumerated settings are cast at the
-- read site (fulfil_payment casts referral_amount to numeric and reward_type to
-- the reward_type enum), and per-key validation on save lives in the
-- admin-settings Edge Function. One column type keeps the admin editor and the
-- allowlist policy uniform across keys.
--
-- display_safe IS the Display_Safe_Keys allowlist from Requirement 9, expressed
-- as data rather than as a literal key list inside a policy. It defaults to
-- false, so a setting added later is private until someone deliberately marks
-- it readable: the safe direction to fail.

create table public.settings (
  key          text primary key,
  value        text not null,
  display_safe boolean not null default false,
  updated_at   timestamptz not null default now()
);

comment on table public.settings is
  'Admin-editable configuration. Client roles read only rows where display_safe = true, via settings_select_display_safe (migration 0010).';

comment on column public.settings.display_safe is
  'The Display_Safe_Keys allowlist as data. Default false: a new key is service-role only until explicitly published. answer_reveal_mode must stay false (Requirements 9.9, 6.13).';

-- ---------------------------------------------------------------------------
-- Seed
-- ---------------------------------------------------------------------------
-- Idempotent: on conflict do nothing, so re-running the migration set never
-- overwrites a value an admin has since edited through the Admin_Portal.
--
-- Requirement 24.1: referral_amount 9, reward_type cash, payout_threshold 100,
-- reward_on every_purchase. These four are display-safe because the front end
-- renders them - the referral amount on the product page, the threshold on the
-- Earnings view (Requirement 25 criteria 4 and 5).
--
-- Requirement 20.12 and 9.9: answer_reveal_mode is seeded answered_only with
-- display_safe = false. It governs how much of the answer key the grading
-- function returns, so no client role may read it; the Grade_Quiz_Function
-- reads it through the service role only.
--
-- The brand, contact, banner, and hero copy keys replace the BRAND_NAME,
-- CONTACT_EMAIL_FALLBACK, HERO_HEADLINE_FALLBACK, and HERO_SUBHEAD_FALLBACK
-- constants removed from config.js, so copy is editable without a deploy. All
-- display-safe: they are rendered to anonymous visitors by definition.
-- announcement_banner seeds empty, which the front end treats as "no banner".

insert into public.settings (key, value, display_safe) values
  ('referral_amount',     '9',                    true),
  ('reward_type',         'cash',                 true),
  ('payout_threshold',    '100',                  true),
  ('reward_on',           'every_purchase',       true),
  ('answer_reveal_mode',  'answered_only',        false),
  ('brand_name',          'ArchPrep PH',          true),
  ('contact_email',       'rehinaneel@gmail.com', true),
  ('announcement_banner', '',                     true),
  ('hero_headline',       'Pass the Architect Licensure Exam with confidence.', true),
  ('hero_subhead',        'Focused review materials and exam-style practice quizzes for Filipino architecture graduates.', true)
on conflict (key) do nothing;

-- =======================================================================
-- 0005_rls_baseline.sql
-- =======================================================================
-- 0005_rls_baseline.sql
-- Platform v2 default-deny baseline: revoke every client privilege in the
-- public schema, stop future objects from inheriting one, and enable RLS on
-- every table.
--
-- This migration grants NOTHING back. Every deliberate client privilege is
-- added by 0006-0010:
--   0006  questions lockdown (service_role select only, no client grant ever)
--   0007  profiles select + column-level update
--   0008  catalog select (products minus material_path, quizzes, pack_quizzes)
--   0009  owner-scoped select on orders, enrollments, quiz_attempts,
--         payout_requests, referrals (column-restricted)
--   0010  settings display-safe allowlist
-- If a table or column is not named in one of those files, no client role can
-- reach it. That is the whole point of this file: a policy is powerless without
-- a grant, and a grant is powerless without a policy.
--
-- Runs after 0003, so the function revokes below also cover gen_ref_code(),
-- handle_new_user(), mask_email(), and guard_profile_columns(). Re-runnable:
-- every statement here is idempotent.
--
-- Requirements: 5.1, 5.2

-- ---------------------------------------------------------------------------
-- 1. Default privileges — close the door on objects that do not exist yet
-- ---------------------------------------------------------------------------
-- Supabase ships permissive default privileges on the public schema, so a table
-- created by a later migration would silently arrive with client privileges
-- attached. These statements flip that default to "nothing", which makes every
-- grant in 0006-0010 a deliberate, reviewable act.
--
-- ALTER DEFAULT PRIVILEGES applies only to objects created by the role that
-- runs it (FOR ROLE defaults to the current role). Migrations are applied as
-- `postgres`, which is the same role Supabase's permissive defaults are
-- attached to, so the plain form is the correct one here. An object created by
-- some other role from the dashboard is outside its reach — hence the blanket
-- revokes in section 2, which catch whatever already exists.

alter default privileges in schema public
  revoke all on tables from anon, authenticated;

alter default privileges in schema public
  revoke all on sequences from anon, authenticated;

-- Functions are the important one. A new function's EXECUTE privilege is
-- granted to PUBLIC by default, and PostgREST exposes every function in the
-- public schema as an RPC endpoint. Without this, a SECURITY DEFINER function
-- added later (fulfil_payment, which writes orders, enrollments, and referrals
-- as its owner) would be callable by `authenticated` through PUBLIC even after
-- an explicit `revoke ... from anon, authenticated`. Revoking from anon and
-- authenticated alone is not enough; PUBLIC has to go too.

alter default privileges in schema public
  revoke execute on functions from anon, authenticated;

alter default privileges in schema public
  revoke execute on functions from public;

-- Deliberately NOT touched: default privileges ON TYPES and ON SCHEMAS.
-- PUBLIC holds USAGE on types by default, and the client roles need that USAGE
-- to read and filter the enum-typed columns created in 0001 (products.type,
-- orders.status, referrals.status, and the rest). Revoking it would break the
-- published-catalog read in 0008 at the type layer, not the privilege layer,
-- which is a confusing failure for zero security gain — enum USAGE discloses
-- nothing on its own.

-- ---------------------------------------------------------------------------
-- 2. Revoke what already exists
-- ---------------------------------------------------------------------------
-- Every table from 0001, 0002, and 0004 was created under Supabase's permissive
-- defaults. This is the sweep that undoes that. It is a blanket revoke rather
-- than a per-table list on purpose: a table someone forgets to add to a list
-- stays exposed, whereas ALL TABLES cannot be forgotten.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

-- ALL FUNCTIONS covers functions, aggregates, and window functions but not
-- procedures; ALL ROUTINES covers procedures as well. Using ROUTINES means a
-- procedure added later is caught by the same sweep.
--
-- PUBLIC is included for the reason given in section 1. This does not disturb
-- the trigger functions from 0003: EXECUTE on a trigger function is checked
-- when the trigger is CREATED, not each time it fires, so revoking EXECUTE
-- from the client roles leaves on_auth_user_created and
-- profiles_guard_columns working exactly as before. Those functions are never
-- called directly by a client role, which is why revoking is not merely safe
-- but correct — a client-callable path into handle_new_user() or
-- guard_profile_columns() would be a hole, not a feature.
--
-- Function bodies are unaffected too: a SECURITY DEFINER function runs as its
-- owner, and an owner keeps its privileges regardless of what PUBLIC holds, so
-- mask_email() stays callable from inside fulfil_payment().

revoke all on all routines in schema public from anon, authenticated;
revoke all on all routines in schema public from public;

-- ---------------------------------------------------------------------------
-- 3. USAGE on schema public is RETAINED
-- ---------------------------------------------------------------------------
-- No revoke of `usage on schema public` from anon or authenticated, and this is
-- deliberate. Schema USAGE is a prerequisite for exercising any privilege on an
-- object inside that schema, so dropping it would break the published-catalog
-- read (0008) and every owner-scoped read (0007, 0009, 0010) that the front end
-- depends on, and PostgREST itself needs it to resolve names for the roles it
-- switches into.
--
-- Retaining USAGE costs nothing here. USAGE alone confers no ability to read,
-- write, or even confirm the contents of a single row — it only permits name
-- resolution. With sections 1 and 2 applied, a client role holds schema USAGE
-- and zero object privileges, which is exactly the intended baseline: the door
-- to the building is open, every room inside is locked.

-- ---------------------------------------------------------------------------
-- 4. Enable RLS on every table — all 13, no exceptions
-- ---------------------------------------------------------------------------
-- Including the tables that will never get a client policy (questions,
-- payment_incidents, admin_bootstrap_emails). Enabling RLS on a table with no
-- policies is the strongest state available: zero rows for a select, a
-- policy-violation error for a write (Requirement 5.3). Leaving RLS off on a
-- service-role-only table would mean a single accidental future grant exposes
-- the whole table.

alter table public.profiles                enable row level security;
alter table public.admin_bootstrap_emails  enable row level security;
alter table public.products                enable row level security;
alter table public.quizzes                 enable row level security;
alter table public.pack_quizzes            enable row level security;
alter table public.questions               enable row level security;
alter table public.orders                  enable row level security;
alter table public.enrollments             enable row level security;
alter table public.quiz_attempts           enable row level security;
alter table public.referrals               enable row level security;
alter table public.payment_incidents       enable row level security;
alter table public.payout_requests         enable row level security;
alter table public.settings                enable row level security;

-- ---------------------------------------------------------------------------
-- 5. Force RLS on the four tables that carry identity, money, and access
-- ---------------------------------------------------------------------------
-- A table owner normally bypasses RLS. FORCE ROW LEVEL SECURITY removes that
-- exemption, so the owner is filtered by the same policies as everyone else.
-- Applied to the tables where an owner-privileged query that quietly ignored
-- the row filter would be worst: profiles (identity and is_admin), orders and
-- enrollments (money and access), referrals (rewards).
--
-- Roles holding the BYPASSRLS attribute are unaffected by FORCE — that is how
-- the Edge Functions keep working. `service_role` has BYPASSRLS, so the
-- webhook's writes to orders, enrollments, and referrals proceed, and
-- fulfil_payment runs as its owner `postgres`, which also holds BYPASSRLS on
-- Supabase. Verify both on first apply with:
--   select rolname, rolbypassrls from pg_roles
--    where rolname in ('postgres', 'service_role');
-- If either came back false, fulfil_payment's writes would fail closed against
-- zero policies rather than fail open, but the webhook would stop fulfilling
-- payments, so this is a deploy-time check worth doing once.

alter table public.profiles     force row level security;
alter table public.orders       force row level security;
alter table public.enrollments  force row level security;
alter table public.referrals    force row level security;

-- =======================================================================
-- 0006_rls_questions.sql
-- =======================================================================
-- 0006_rls_questions.sql
-- The answer-key guarantee, stated in full.
--
-- public.questions holds correct_key and explanation — the Answer_Fields. This
-- file is the auditable statement that no browser-reachable role can read them:
--   * zero grants to anon, to authenticated, and to PUBLIC
--   * zero RLS policies (RLS itself was enabled in 0005)
--   * select granted to service_role only
--
-- That combination is stronger than a filtered policy. Postgres checks table
-- privileges BEFORE it consults RLS, so a client request never reaches a row
-- filter that could be wrong: `quizzes?select=*,questions(*)` through PostgREST,
-- a select of correct_key alone, an aggregate over explanation, an order-by on
-- either column — all fail at the privilege layer, for every session state,
-- including a session belonging to a user who legitimately owns the quiz
-- (Requirements 6.2, 6.3, 6.4, 6.5, 6.9).
--
-- DO NOT, IN ANY FUTURE MIGRATION:
--   1. grant any privilege on public.questions to anon, authenticated, or
--      PUBLIC — not even a column-level grant on question_text or options.
--      Question content reaches the browser only through get-quiz, which strips
--      the Answer_Fields server-side (Requirement 6.7).
--   2. create any RLS policy on public.questions. A policy is useless without a
--      grant, so a policy here can only be a step towards adding one. There is
--      no legitimate reason for either.
--   3. create a client-callable SECURITY DEFINER function, procedure, or view
--      that reads public.questions. A definer routine runs with its owner's
--      privileges, which is precisely the hole this file exists to prevent: it
--      would hand a client role the read that the missing grant denies. Every
--      routine that touches this table must be callable by service_role only
--      (`revoke all on function ... from anon, authenticated, public`), and any
--      view over it must be created `with (security_invoker = true)` so the
--      caller's own (absent) privileges apply.
--
-- Requirement 6.6: the Answer_Fields are read through the Service_Role inside
-- the get-quiz and grade-quiz Edge Functions only. The grant below is what
-- makes those two paths work and is the complete set of read paths that exist.
-- admin-questions writes the table through the same role.
--
-- Requirements: 6.1, 6.6
-- Declared in design.md "Policy inventory": questions — client policies: none,
-- client grants: none. The test for Requirement 5.4 asserts exactly that.
-- Re-runnable: every statement is idempotent.

-- ---------------------------------------------------------------------------
-- 1. Zero client privileges
-- ---------------------------------------------------------------------------
-- 0005 already swept every table in the schema with a blanket revoke. This
-- repeats it for this one table on purpose: the guarantee should be readable in
-- one file rather than inferred from a wildcard three migrations back, and a
-- privilege granted out-of-band (a dashboard session, a hotfix) is removed
-- again the next time the migration set is applied to a fresh database.
--
-- PUBLIC is named explicitly because a grant to PUBLIC is inherited by every
-- role, so revoking from anon and authenticated alone would not close it.

revoke all on public.questions from anon, authenticated;
revoke all on public.questions from public;

-- ---------------------------------------------------------------------------
-- 2. service_role only
-- ---------------------------------------------------------------------------
-- The read path for get-quiz and grade-quiz (Requirement 6.6).

grant select on public.questions to service_role;

-- Writes for admin-questions (Requirement 8.5). Supabase's default privileges
-- already give service_role full access to tables in the public schema; naming
-- the write privileges here means the admin path does not depend on that
-- default surviving, and it keeps every privilege this table has in one place.
-- service_role is never exposed to a browser — it lives in Edge Function
-- secrets — so this widens nothing that section 1 closed.

grant insert, update, delete on public.questions to service_role;

-- ---------------------------------------------------------------------------
-- 3. The prohibition, recorded on the objects themselves
-- ---------------------------------------------------------------------------
-- 0001 set a table comment pointing here; this replaces it with the full rule,
-- so anyone who inspects the table from psql or the dashboard sees the
-- constraint before they consider adding a policy.

comment on table public.questions is
  'Answer keys (correct_key, explanation). Readable by service_role only, through the get-quiz and grade-quiz Edge Functions. NEVER add a grant to anon/authenticated/PUBLIC, NEVER add an RLS policy, and NEVER add a client-callable SECURITY DEFINER routine or non-security_invoker view over this table. See migration 0006_rls_questions.sql.';

comment on column public.questions.correct_key is
  'Answer_Field. Omitted from every get-quiz payload (Requirement 6.7) and revealed by grade-quiz only per answer_reveal_mode (Requirements 6.10, 6.12). Never selectable by a client role.';

comment on column public.questions.explanation is
  'Answer_Field. Same exposure rules as correct_key: service_role reads it, grade-quiz decides whether it is revealed, and no client role may select it.';

-- ---------------------------------------------------------------------------
-- 4. Fail-closed self-check
-- ---------------------------------------------------------------------------
-- Asserts the two claims this file makes, at apply time, against the live
-- catalog: zero policies on the table, and zero table-level or column-level
-- privileges held by anon, authenticated, or PUBLIC. If a policy or grant was
-- added out-of-band and somehow survived section 1, the migration aborts rather
-- than reporting success over a weakened model.
--
-- This is a point-in-time assertion: it sees only what exists when it runs, and
-- on a fresh apply that is migrations 0001-0005. The enduring check is the
-- policy-enumeration test for Requirement 5.4, which runs against the deployed
-- database and compares every live policy and grant to the declared inventory.
-- The two are complementary, not redundant — this one fails the deploy, that
-- one fails the build.

do $$
declare
  v_policies       integer;
  v_table_grants   integer;
  v_column_grants  integer;
  v_client_roles   text[] := array['anon', 'authenticated'];
begin
  select count(*) into v_policies
    from pg_policies
   where schemaname = 'public'
     and tablename  = 'questions';

  if v_policies > 0 then
    raise exception
      'questions lockdown violated: % RLS policy(ies) exist on public.questions. Requirement 6.1 allows zero.',
      v_policies;
  end if;

  -- grantee 0 in an aclitem is PUBLIC.
  select count(*) into v_table_grants
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    cross join lateral aclexplode(c.relacl) a
   where n.nspname = 'public'
     and c.relname = 'questions'
     and (a.grantee = 0 or a.grantee::regrole::text = any (v_client_roles));

  select count(*) into v_column_grants
    from pg_attribute att
    join pg_class c     on c.oid = att.attrelid
    join pg_namespace n on n.oid = c.relnamespace
    cross join lateral aclexplode(att.attacl) a
   where n.nspname = 'public'
     and c.relname = 'questions'
     and att.attnum > 0
     and not att.attisdropped
     and (a.grantee = 0 or a.grantee::regrole::text = any (v_client_roles));

  if v_table_grants > 0 or v_column_grants > 0 then
    raise exception
      'questions lockdown violated: % table privilege(s) and % column privilege(s) held by anon/authenticated/PUBLIC on public.questions. Requirement 6.1 allows zero.',
      v_table_grants, v_column_grants;
  end if;

  raise notice
    'questions lockdown verified: zero policies, zero client grants, select granted to service_role.';
end;
$$;

-- =======================================================================
-- 0007_rls_profiles.sql
-- =======================================================================
-- 0007_rls_profiles.sql
-- Platform v2 profiles access: own-row read, own-row update of exactly two
-- columns, and nothing else. This is the first migration after the 0005
-- baseline to grant a client privilege back, so every statement below is a
-- deliberate, reviewable widening of a default-deny table.
--
-- Declared client surface for public.profiles (design policy inventory):
--   policies : profiles_select_own, profiles_update_own
--   grants   : SELECT; UPDATE(display_name, gcash_number)
-- Nothing else. The 3.13 inventory test asserts equality against exactly that,
-- so an extra policy or a widened grant added later fails the suite.
--
-- Depends on 0001 (public.profiles), 0003 (guard_profile_columns() and the
-- profiles_guard_columns before-update trigger, the defence-in-depth layer
-- behind the column-level grant here), and 0005 (RLS enabled, FORCE RLS, and
-- every client privilege revoked). Re-runnable: the grants are idempotent and
-- each policy is dropped before it is created.
--
-- Requirements: 7.1, 9.1, 9.2, 9.3, 3.5

-- ---------------------------------------------------------------------------
-- 1. Grants — the column-level guard that Postgres actually provides
-- ---------------------------------------------------------------------------
-- Postgres has no column-level RLS, so Requirements 9.2 and 9.3 are enforced
-- with column-level GRANT, which is the mechanism designed for this job.
-- `authenticated` may write display_name and gcash_number and no other column.
--
-- UPDATE profiles SET is_admin = true WHERE id = auth.uid() is rejected with
-- "permission denied for column is_admin" at the privilege layer, before any
-- policy runs and regardless of what the row filter would have allowed.
-- ref_code, referred_by, email, and id are withheld the same way (9.3). The
-- trigger from 0003 repeats the check inside the statement so the guarantee
-- survives someone widening this grant later; it is the backstop, not the
-- primary control.
--
-- SELECT is granted on the whole table rather than a column list. Withholding
-- a column here would buy nothing: profiles_select_own restricts the reader to
-- their own row, and is_admin, ref_code, referred_by, and email on that row are
-- all values the front end legitimately renders (the account menu, the referral
-- link, the admin shell's is_admin check). Unreadable is not the requirement;
-- unwritable is, and that is what the UPDATE grant delivers.

grant select on public.profiles to authenticated;

grant update (display_name, gcash_number) on public.profiles to authenticated;

-- Deliberately NOT granted:
--   * anything at all to anon. Requirement 7.6: an unauthenticated select from
--     profiles returns zero rows, which it does at the privilege layer.
--   * INSERT. See section 3.
--   * DELETE. See section 3.

-- ---------------------------------------------------------------------------
-- 2. Policies — own row only
-- ---------------------------------------------------------------------------
-- Requirement 7.1 (read) and 9.1 (update). Both are scoped to `authenticated`,
-- so anon has no policy on this table even if a grant were ever added by
-- accident. FORCE RLS from 0005 means the table owner is filtered by these
-- policies too; service_role and postgres pass through on BYPASSRLS, which is
-- how handle_new_user() and the admin functions keep working.

drop policy if exists profiles_select_own on public.profiles;

create policy profiles_select_own on public.profiles
  for select to authenticated
  using (id = auth.uid());

-- USING filters the rows the update may target; WITH CHECK re-validates the
-- post-update row. Both are needed: without WITH CHECK a user could move their
-- own row to another id and keep it, and with the grant covering only
-- display_name and gcash_number that is already impossible, but the policy
-- should not depend on the grant to stay correct.

drop policy if exists profiles_update_own on public.profiles;

create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- Requirement 3.5 is satisfied by the pair above plus the column grant: the
-- Account settings view updates display_name and gcash_number on the user's own
-- row through PostgREST, with no Edge Function in the path.

-- ---------------------------------------------------------------------------
-- 3. No INSERT policy and no DELETE policy — both absences are the design
-- ---------------------------------------------------------------------------
-- NO INSERT POLICY, and no INSERT grant. A profiles row is created only by
-- handle_new_user() firing on the auth.users insert (migration 0003,
-- Requirements 3.1 and 3.2). That trigger is the single writer, which is what
-- makes "exactly one profile per user, with a unique ref_code and is_admin
-- derived from admin_bootstrap_emails" true by construction. A client-side
-- insert path would let a user create a second profile row, choose their own
-- ref_code, or set is_admin on the way in — none of which the update guard in
-- section 1 can catch, because that guard only compares an old row to a new
-- one. The absence of the insert path is therefore load-bearing, not an
-- omission.
--
-- NO DELETE POLICY, and no DELETE grant. A profiles row is removed only by
-- cascade from auth.users (profiles.id references auth.users(id) on delete
-- cascade, migration 0001), so account deletion is an auth-layer action and the
-- profile follows it. Allowing a client delete would orphan the rows that point
-- at the profile — orders, enrollments, quiz_attempts, referrals, and the
-- referred_by self-reference other profiles hold on this row's ref_code — and
-- would hand a user a way to erase their own referral attribution after a
-- purchase. Deletion belongs to auth.users alone.
--
-- Requirement 5.3 supplies the behaviour for both: with RLS enabled and no
-- policy, a client insert or delete is rejected with a policy-violation error.
-- The missing grants mean it is rejected one layer earlier still.

comment on table public.profiles is
  'Requirements 7.1, 9.1. Client surface: profiles_select_own (own row read), profiles_update_own with UPDATE granted on display_name and gcash_number only. No insert policy - rows come from handle_new_user() alone. No delete policy - rows go by cascade from auth.users alone.';

-- =======================================================================
-- 0008_rls_catalog.sql
-- =======================================================================
-- 0008_rls_catalog.sql
-- Platform v2 public catalog read: the only three tables a visitor with no
-- session may read. Runs after 0005, which revoked every client privilege in
-- the public schema and enabled RLS everywhere, so these grants and policies
-- are additive on top of a default-deny baseline.
--
-- Two halves, both required. A grant without a policy returns zero rows because
-- RLS is enabled; a policy without a grant fails at the privilege layer before
-- the row filter is consulted. The catalog is readable only because both halves
-- are present, and only for the rows and columns named here.
--
-- Requirements: 9.4, 9.5, 18.7

-- ---------------------------------------------------------------------------
-- 1. products — column-level select, material_path deliberately withheld
-- ---------------------------------------------------------------------------
-- Requirement 18.7: the browser must hold zero Storage object paths that
-- resolve without a signature. A private-bucket path resolves to nothing
-- without a signature, so exposing material_path would arguably satisfy the
-- criterion on its own — but withholding it means the browser never learns the
-- object layout at all, and the criterion becomes flatly testable as "the
-- client-visible product payload contains no material path". Materials are
-- reached one way only: issue-material-url, which checks enrollments for the
-- verified uid and mints a 300-second signed URL.
--
-- This is a column-level grant precisely so the omission is enforced by the
-- privilege layer rather than by every caller remembering to write an explicit
-- column list. `select *` from a client role returns the granted columns via
-- PostgREST; an explicit `select=material_path` is rejected with
-- `permission denied for column material_path`. Postgres has no column-level
-- RLS, so a grant is the mechanism actually designed for this.
--
-- thumbnail_path IS granted. Thumbnails live in a separate PUBLIC bucket and
-- have to render for anonymous visitors, so that path is not a secret.
--
-- Every other column in the 0001 definition is named below, including
-- created_at. Adding a column to products in a later migration does NOT widen
-- this grant — the new column stays unreadable by client roles until someone
-- adds it here on purpose, which is the behaviour we want.

grant select (
  id,
  slug,
  type,
  subject,
  title,
  subtitle,
  description,
  price_php,
  currency,
  thumbnail_path,
  includes,
  published,
  sort_order,
  created_at
) on public.products to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. quizzes and pack_quizzes — full table select
-- ---------------------------------------------------------------------------
-- Requirement 9.8: quizzes holds metadata only (slug, title, subject,
-- timer_minutes, published). Question text, correct_key, and explanation live
-- in public.questions, which carries zero client grants and zero policies, so
-- a full select grant here discloses nothing an answer key depends on.
--
-- pack_quizzes is a join table of two foreign keys and a sort order. It carries
-- no secret of its own; its rows are gated by the parent product's published
-- flag in section 3.

grant select on public.quizzes      to anon, authenticated;
grant select on public.pack_quizzes to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Published-only select policies
-- ---------------------------------------------------------------------------
-- Requirements 9.4 and 9.5: client reads return exactly the published subset.
-- Policy names are fixed by the design's policy inventory table and are
-- asserted by the rls-policy-inventory suite; renaming one is a test failure.
--
-- SELECT only. No INSERT, UPDATE, or DELETE policy and no such grant exists on
-- any of the three tables — the catalog is written only through the admin-*
-- Edge Functions using the service role.
--
-- The drop-then-create form keeps this migration re-runnable; Postgres has no
-- `create policy if not exists`.

drop policy if exists products_select_published on public.products;

create policy products_select_published on public.products
  for select to anon, authenticated
  using (published = true);

drop policy if exists quizzes_select_published on public.quizzes;

create policy quizzes_select_published on public.quizzes
  for select to anon, authenticated
  using (published = true);

-- Requirement 9.4: pack_quizzes has no published column of its own, so
-- visibility resolves through the PARENT PRODUCT's flag. A quiz mapped only to
-- unpublished packs is therefore invisible to client roles, and unpublishing a
-- product immediately hides its mappings without touching pack_quizzes rows.
--
-- The subquery runs as the querying role, which is why it works: section 1
-- granted that role select on products.id and products.published. It is also
-- subject to products' own RLS, so products_select_published filters it a
-- second time — the predicate and the parent policy agree, which makes the
-- rule fail closed from both directions.
--
-- Qualifying the outer table as `pack_quizzes.product_id` (and aliasing the
-- inner one as `p`) keeps the correlation unambiguous; an unqualified
-- `product_id` would resolve against the subquery's table if products ever
-- gained a column by that name, silently turning the filter into a tautology.

drop policy if exists pack_quizzes_select_published on public.pack_quizzes;

create policy pack_quizzes_select_published on public.pack_quizzes
  for select to anon, authenticated
  using (exists (
    select 1
    from public.products p
    where p.id = pack_quizzes.product_id
      and p.published = true
  ));

-- =======================================================================
-- 0009_rls_owner_scoped.sql
-- =======================================================================
-- 0009_rls_owner_scoped.sql
-- Platform v2 owner-scoped reads and the service-role-only write model for the
-- money and access tables: orders, enrollments, quiz_attempts, referrals,
-- payout_requests, payment_incidents, admin_bootstrap_emails.
--
-- Depends on 0002 for the tables and on 0005 for the revoke-first baseline
-- (every client privilege in the public schema is already revoked and RLS is
-- already enabled on all 13 tables). Everything granted below is therefore
-- additive and deliberate: if a table or a column is not named in this file, no
-- client role can reach it.
--
-- The shape of this file is five SELECT grants, five own-row SELECT policies,
-- and two tables that are named only in comments because they get nothing at
-- all. There is no INSERT, UPDATE, or DELETE grant and no such policy anywhere
-- in it. Every write to these tables goes through the service role inside an
-- Edge Function (create-payment, hitpay-webhook, grade-quiz, request-payout,
-- admin-*), which is what Requirement 8 asks for.
--
-- Re-runnable: each policy is dropped first, and GRANT is idempotent.
--
-- Requirements: 7.2, 8.1, 8.5

-- ---------------------------------------------------------------------------
-- 1. orders, enrollments, quiz_attempts — read own, never write
-- ---------------------------------------------------------------------------
-- SELECT only, and only for `authenticated`. `anon` gets nothing on any of the
-- three, so an unauthenticated read fails at the privilege layer before RLS is
-- consulted (Requirement 7.6). auth.uid() is null for anon anyway, so the row
-- filter would return zero rows even if the grant existed — withholding the
-- grant means the answer is "no privilege", not "no matching rows".

grant select on public.orders        to authenticated;
grant select on public.enrollments   to authenticated;
grant select on public.quiz_attempts to authenticated;

-- Requirement 7.2. `user_id = auth.uid()` is the whole filter. A request that
-- asks for another user's rows (`orders?user_id=eq.<other>`) is not an error —
-- the filter is ANDed with the policy, so it returns zero rows (Requirement
-- 7.5). That is the correct behaviour: a 200 with an empty array discloses
-- nothing, not even whether the other user's row exists.

drop policy if exists orders_select_own on public.orders;
create policy orders_select_own on public.orders
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists enrollments_select_own on public.enrollments;
create policy enrollments_select_own on public.enrollments
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists quiz_attempts_select_own on public.quiz_attempts;
create policy quiz_attempts_select_own on public.quiz_attempts
  for select to authenticated
  using (user_id = auth.uid());

-- No INSERT, UPDATE, or DELETE grant and no such policy on any of the three
-- (Requirement 8.1). Both halves matter and neither is redundant:
--   * no grant  -> the statement is rejected with "permission denied for table"
--   * no policy -> even if a grant were added later, the write is still
--                  rejected with a policy-violation error (Requirements 8.2,
--                  8.3), because RLS is enabled with zero permissive policies
--                  for the operation.
-- Writes come from: orders and enrollments via create-payment and
-- hitpay-webhook (service role, Requirement 8.4), quiz_attempts via grade-quiz
-- only — the client never inserts an attempt, so a client cannot fabricate a
-- score.
--
-- Deliberately absent: an `enrollments` insert policy of the shape
-- `with check (user_id = auth.uid())`. It looks safe and is not. It would let
-- any logged-in user grant themselves access to any product for free, which is
-- exactly the attack Requirement 8.6 tests for. Do not add it.

-- ---------------------------------------------------------------------------
-- 2. referrals — read own, buyer identity withheld at the grant
-- ---------------------------------------------------------------------------
-- A column-level grant naming 12 of the table's 14 columns. The two withheld
-- are `buyer_user_id` and `referrer_user_id`.
--
-- `buyer_user_id` is withheld because the referrer has no business learning who
-- bought through their link. The ledger renders `buyer_masked`
-- (juan****@gmail.com), computed once by the service role at insert time, so
-- the front end has nothing to display beyond it and nothing to leak.
--
-- `referrer_user_id` is withheld because it is the referrer's own id, already
-- known to them from their session, so granting it buys nothing while widening
-- the surface.
--
-- Column-level GRANT rather than a view: PostgREST honours column privileges
-- directly, so `referrals?select=buyer_user_id` is rejected with "permission
-- denied for column buyer_user_id" and `select=*` expands to the granted
-- columns only. A view would need its own grant, its own RLS consideration, and
-- would still leave the base table one grant away from exposure.

grant select (id, referrer_ref_code, order_id, product_id, product_title,
              amount_php, reward_type, status, created_at, paid_at,
              buyer_masked, notes)
  on public.referrals to authenticated;

-- Requirement 7.2 for referrals: the owner is the REFERRER, not the buyer, so
-- the filter is `referrer_user_id = auth.uid()` rather than `user_id`.
--
-- This looks wrong at first read and is not: the USING clause references
-- `referrer_user_id`, a column the role has NO select privilege on. That is
-- legal and intended. Column privileges govern what a query may return;
-- an RLS policy expression is evaluated by the system as part of the row
-- filter, not as part of the user's select list, so it may read any column of
-- the table. The row filter therefore works while the column itself stays
-- unreadable. Removing `referrer_user_id` from the policy to "match the grant"
-- would break owner scoping entirely — leave it.

drop policy if exists referrals_select_own on public.referrals;
create policy referrals_select_own on public.referrals
  for select to authenticated
  using (referrer_user_id = auth.uid());

-- No write grant and no write policy on referrals (Requirement 8.1). Rows are
-- inserted by fulfil_payment inside the webhook transaction and updated by
-- admin-* functions when a payout is marked paid.

-- ---------------------------------------------------------------------------
-- 3. payout_requests — read own status, request through the Edge Function
-- ---------------------------------------------------------------------------
-- A user may watch their own payout requests move from requested to paid or
-- rejected, and may not create one. `request-payout` recomputes the eligible
-- balance from `referrals` server-side before inserting, so a client cannot
-- request more than it has earned; a client-side insert grant would make that
-- recomputation bypassable and the amount client-supplied.

grant select on public.payout_requests to authenticated;

drop policy if exists payout_requests_select_own on public.payout_requests;
create policy payout_requests_select_own on public.payout_requests
  for select to authenticated
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- 4. payment_incidents — zero grants, zero policies, stated explicitly
-- ---------------------------------------------------------------------------
-- There are no statements for this table below, and the absence is the point.
-- An absence is invisible to a reviewer, so it is written down here instead:
--
--   payment_incidents: ZERO grants to anon, ZERO grants to authenticated,
--   ZERO policies. Service role only.
--
-- `payload` holds the raw HitPay webhook body for forensics and can contain
-- payer details, so no client role may reach this table by any route. RLS is
-- already enabled on it by 0005, so the state is the strongest available: zero
-- rows for a select, a policy-violation error for a write. The admin portal
-- reads incidents through the `admin-incidents` Edge Function, never through
-- PostgREST.
--
-- The revoke below is a no-op after 0005's blanket sweep. It is kept anyway so
-- this file states the intent for the table it is responsible for, and so the
-- intent survives someone granting a privilege from the dashboard between
-- migrations. Do not replace it with a grant.

revoke all on public.payment_incidents from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5. admin_bootstrap_emails — zero grants, zero policies, stated explicitly
-- ---------------------------------------------------------------------------
--   admin_bootstrap_emails: ZERO grants to anon, ZERO grants to authenticated,
--   ZERO policies. Service role only.
--
-- The table holds the owner email addresses that `handle_new_user()` checks to
-- set `is_admin` at signup. It is read by that trigger function, which runs as
-- its owner and therefore needs no client privilege, and it is edited by an
-- admin function. Exposing it to a client role would publish the owners' email
-- addresses and hand an attacker the exact list of addresses worth taking over.

revoke all on public.admin_bootstrap_emails from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 6. What this file deliberately does not do
-- ---------------------------------------------------------------------------
-- Requirement 8.5 covers products, pack_quizzes, quizzes, questions, and
-- settings: zero client insert, update, and delete policies, written through
-- admin functions with the service role. Their SELECT grants and policies live
-- in 0006 (questions: none at all), 0008 (catalog), and 0010 (settings); none
-- of those files issues a write grant either, and this file adds none on their
-- behalf. The declared client-privilege set across 0006-0010 is exactly the
-- policy inventory table in the design, and the inventory test in task 3.13
-- asserts equality against it — so a convenience policy added here later fails
-- that test even when every functional test still passes.
--
-- Policies declared by this file, for that test:
--   orders          orders_select_own           SELECT
--   enrollments     enrollments_select_own      SELECT
--   quiz_attempts   quiz_attempts_select_own    SELECT
--   referrals       referrals_select_own        SELECT on 12 named columns
--   payout_requests payout_requests_select_own  SELECT
--   payment_incidents        none               none
--   admin_bootstrap_emails   none               none

-- =======================================================================
-- 0010_rls_settings.sql
-- =======================================================================
-- 0010_rls_settings.sql
-- Platform v2 settings allowlist: the one client privilege on public.settings.
--
-- Depends on 0004 (creates the table and seeds the ten rows) and 0005 (revokes
-- every client privilege in the public schema and enables RLS on settings).
-- After 0005, settings is reachable by no client role at all; this file hands
-- back exactly one capability — read the rows an admin has marked display-safe.
--
-- Read-only by design. There is no insert, update, or delete grant and no such
-- policy, so the only write path to settings is the admin-settings Edge
-- Function running as the service role, which also carries the per-key
-- validation (accepting cash/credit for reward_type and
-- answered_only/full_reveal for answer_reveal_mode).
--
-- Re-runnable: the grant is idempotent by nature and the policy is dropped
-- before it is created.
--
-- Requirements: 9.6, 9.7, 6.13

-- ---------------------------------------------------------------------------
-- 1. Grant
-- ---------------------------------------------------------------------------
-- A whole-table select grant rather than a column list. Unlike products, where
-- material_path is withheld (0008), and referrals, where the buyer and referrer
-- identifiers are withheld (0009), settings has no column worth hiding from a
-- row the role is already allowed to see: key, value, display_safe, and
-- updated_at are all safe once the row itself is public. Withholding
-- display_safe in particular would buy nothing, since every visible row has it
-- true by definition of the policy below.
--
-- The grant alone discloses nothing. With RLS enabled and no policy, the select
-- privilege returns zero rows; the privilege and the policy have to agree
-- before a single row is visible.

grant select on public.settings to anon, authenticated;

-- Belt and braces on the absence of a write path. 0005 already revoked these,
-- so this changes nothing today — it states the intent in the file a reader
-- will open when they ask "can a client write a setting?", and it survives a
-- later accidental blanket grant in the schema.

revoke insert, update, delete, truncate, references, trigger
  on public.settings from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. The allowlist policy
-- ---------------------------------------------------------------------------
-- Requirement 9.6 asks for a select policy permitting rows whose key is a
-- member of Display_Safe_Keys, and 9.7 requires zero rows for anything outside
-- that set. The allowlist lives in the data as settings.display_safe (0004),
-- not as a literal key list inside this policy, for two reasons: an admin can
-- publish or unpublish a key without a migration, and a key added later
-- defaults to false, so a new setting is service-role only until someone
-- deliberately publishes it. A hard-coded list would instead have to be edited
-- in lockstep with every key change, and a forgotten edit fails open.
--
-- Requirement 6.13: answer_reveal_mode is seeded display_safe = false, so
-- settings?key=eq.answer_reveal_mode returns zero rows to anon and to
-- authenticated. That setting decides how much of the answer key grade-quiz
-- returns, and grade-quiz reads it through the service role, which is not
-- subject to this policy. Nothing in the database forces that row to stay
-- false — the admin-settings function is what refuses to publish it — but the
-- policy needs no exception for it, and the inventory test (task 3.13) plus the
-- settings allowlist property test (task 3.12) are what keep it honest.
--
-- FOR SELECT only. No `for all`, which would silently create an insert,
-- update, and delete policy too; harmless while the write grants are absent,
-- but it would turn one future careless grant into a write path.
--
-- USING (display_safe = true) is written against the boolean rather than as a
-- bare `using (display_safe)` so a null could never be mistaken for true. The
-- column is NOT NULL, so this is style, not a live hazard.

drop policy if exists settings_select_display_safe on public.settings;

create policy settings_select_display_safe on public.settings
  for select to anon, authenticated
  using (display_safe = true);

comment on policy settings_select_display_safe on public.settings is
  'Requirements 9.6, 9.7, 6.13. Client roles read only rows marked display_safe. answer_reveal_mode is seeded false, so it returns zero rows to every client role.';

-- =======================================================================
-- 0011_fn_fulfil_payment.sql
-- =======================================================================
-- 0011_fn_fulfil_payment.sql
-- Platform v2 fulfilment: public.fulfil_payment(text, numeric, text, jsonb).
--
-- The whole pay -> enrol -> attribute decision lives in ONE function body so it
-- is ONE transaction (Requirement 16.2). supabase-js issues each statement as
-- its own transaction over PostgREST, so this cannot be built correctly in
-- Deno. The hitpay-webhook Edge Function verifies the HMAC, normalises the
-- payload, and hands the entire decision to this RPC.
--
-- Depends on:
--   0001  enum types order_status, enrollment_source, referral_status,
--         reward_type, incident_kind; profiles; products
--   0002  orders (partial unique index on hitpay_payment_id), enrollments
--         (enrollments_user_product_key), referrals (unique order_id,
--         referrals_no_self), payment_incidents
--   0003  mask_email()
--   0004  settings and its seeded referral configuration
--   0005  the revoke-first baseline and FORCE RLS on orders/enrollments/
--         referrals/profiles
--
-- Privileges: SECURITY DEFINER, owned by the migration role (postgres), EXECUTE
-- granted to service_role only (Requirement 8.4). 0005 already flipped default
-- privileges to deny EXECUTE to anon, authenticated and PUBLIC for functions
-- created later, so this function arrives closed; the revokes at the bottom are
-- stated explicitly anyway, because PostgREST exposes every public-schema
-- function as an RPC endpoint and this one writes money and access rows.
--
-- RLS note: orders, enrollments and referrals are FORCE ROW LEVEL SECURITY with
-- zero policies. This body works because the owner role holds BYPASSRLS on
-- Supabase. That is the deploy-time check called out in 0005:
--   select rolname, rolbypassrls from pg_roles
--    where rolname in ('postgres', 'service_role');
-- Both must be true. If the owner lacked BYPASSRLS the writes would fail closed
-- (no silent partial fulfilment), but fulfilment would stop entirely.
--
-- search_path note: pinned to `public, pg_temp` with pg_temp LAST, so a caller
-- cannot redirect this definer function at a shadowed table, and a temp object
-- cannot shadow a public one. pg_catalog is implicitly searched first, so the
-- built-ins used here (round, upper, btrim, now) cannot be shadowed either.
-- mask_email() in 0003 has no search_path of its own, so it inherits this one
-- when called from here; the call is schema-qualified as public.mask_email so
-- resolution of the call itself cannot be diverted. Pinning search_path on
-- mask_email would be the belt-and-braces fix, but 0003 is already applied and
-- is not edited by this task.
--
-- Requirements: 15.1, 15.2, 15.3, 15.4, 15.5, 15.8, 15.9, 16.2, 16.4, 16.5,
--               16.6, 16.10, 23.1, 23.2, 23.3, 23.4, 23.5, 23.6, 23.7, 23.8,
--               24.3, 24.4, 8.4

create or replace function public.fulfil_payment(
  p_payment_id        text,
  p_reported_amount   numeric,
  p_reported_currency text,
  p_payload           jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order      public.orders;
  v_referrer   public.profiles;
  v_reported   numeric;             -- unconstrained: an absurd payload value
  v_fit        numeric(12,2);       -- must not overflow before it is judged
  v_reward_amt numeric(12,2);
  v_reward_ty  public.reward_type;
  v_reward_on  text;
  v_setting    text;
  v_mask       text;
  v_title      text;
begin
  -- (1) Resolve the order and LOCK it. The lock is what serialises overlapping
  --     duplicate deliveries (Requirement 16.6): the second call resumes only
  --     after the first commits, then re-reads the row under READ COMMITTED and
  --     sees status = 'paid'. The unique constraints still backstop it.
  --     The partial unique index on hitpay_payment_id guarantees at most one
  --     matching row (Requirement 15.1: "the single orders row").
  select * into v_order
  from public.orders
  where hitpay_payment_id = p_payment_id
  for update;

  -- (2) Unknown payment identifier (Requirements 15.7, 16.10). Zero writes to
  --     orders, enrollments and referrals; the incident is the only row added,
  --     and it commits so the webhook can answer 200.
  if not found then
    insert into public.payment_incidents
      (kind, hitpay_payment_id, reported_amount, reported_currency, payload)
    values ('unmatched_payment', p_payment_id,
            case when p_reported_amount is not null
                  and p_reported_amount <> 'NaN'::numeric
                  and abs(p_reported_amount) < 10000000000
                 then round(p_reported_amount, 2) end,
            p_reported_currency, p_payload);
    return jsonb_build_object('outcome', 'unmatched');
  end if;

  -- (3) Replay of an already-fulfilled order (Requirement 16.5). Return BEFORE
  --     touching anything, so paid_at stays exactly as the first delivery left
  --     it and the enrollment and referral rows keep every column. A blind
  --     `update ... set paid_at = now()` would satisfy the row counts and still
  --     violate 16.5.
  if v_order.status = 'paid' then
    return jsonb_build_object('outcome', 'already_paid', 'order_id', v_order.id);
  end if;

  -- (4) A completed payment reported against a refunded order is out of order
  --     (Requirement 16.9 in spirit, recorded for admin review). Leave the
  --     order, the enrollment and the referral alone.
  if v_order.status = 'refunded' then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('out_of_order_status', v_order.id, p_payment_id,
            case when p_reported_amount is not null
                  and p_reported_amount <> 'NaN'::numeric
                  and abs(p_reported_amount) < 10000000000
                 then round(p_reported_amount, 2) end,
            p_reported_currency, v_order.amount_php, v_order.currency, p_payload);
    return jsonb_build_object('outcome', 'already_refunded', 'order_id', v_order.id);
  end if;

  -- (5) Paid-amount cross-check (Requirement 15), before any enrollment row,
  --     any referral row, and any status change (15.1).
  --
  --     The comparison value is v_order.amount_php, written by create-payment
  --     from products.price_php. Zero part of it comes from the payload (15.5).
  --     Zero tolerance at two decimals, so an overpayment is a mismatch too
  --     (15.3). A null or NaN reported amount is a mismatch, which is how
  --     "absent or not parseable as a decimal number" lands here.
  --
  --     v_reported is unconstrained numeric and v_fit is the value narrowed for
  --     storage, because payment_incidents.reported_amount is numeric(12,2): an
  --     out-of-range payload amount must be recorded as a mismatch, not raise a
  --     numeric overflow that would roll back the incident and make HitPay
  --     retry a call that can never succeed. The full payload is stored either
  --     way, so nothing is lost when v_fit is null.
  v_reported := p_reported_amount;

  if v_reported is not null
     and v_reported <> 'NaN'::numeric
     and abs(v_reported) < 10000000000 then
    v_fit := round(v_reported, 2);
  else
    v_fit := null;
  end if;

  if v_reported is null
     or v_reported = 'NaN'::numeric
     or round(v_reported, 2) <> round(v_order.amount_php, 2) then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('amount_mismatch', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency, p_payload);
    return jsonb_build_object('outcome', 'amount_mismatch', 'order_id', v_order.id);
  end if;

  -- Currency compared as three-letter codes, trimmed, case-insensitive
  -- (Requirement 15.2). HitPay reports lower case; orders.currency is 'PHP'.
  -- Absent currency is a mismatch (15.4). The status is still 'pending' at this
  -- point, and stays that way (15.3, 15.4).
  if p_reported_currency is null
     or upper(btrim(p_reported_currency)) <> upper(btrim(v_order.currency)) then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('currency_mismatch', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency, p_payload);
    return jsonb_build_object('outcome', 'currency_mismatch', 'order_id', v_order.id);
  end if;

  -- From here the amount and the currency both matched, so zero incident rows
  -- are recorded for this order and fulfilment proceeds (Requirement 15.9).

  -- (6) Mark paid. now() is the transaction timestamp, stored as UTC by
  --     timestamptz (Requirement 16.2).
  update public.orders
     set status  = 'paid',
         paid_at = now()
   where id = v_order.id;

  -- (7) Grant access. The unique constraint IS the idempotency mechanism rather
  --     than a prior-existence check, so it holds under overlapping calls too
  --     (Requirements 16.4, 16.6). do nothing leaves every column of an
  --     existing enrollment untouched, including a comp enrollment for the same
  --     product.
  insert into public.enrollments (user_id, product_id, source, order_id)
  values (v_order.user_id, v_order.product_id, 'purchase', v_order.id)
  on conflict (user_id, product_id) do nothing;

  -- (8) Referral attribution (Requirement 23), inside this same transaction.
  --     No ref_code on the order: zero referral rows, enrollment already
  --     granted above (Requirement 23.8).
  if v_order.ref_code is not null and btrim(v_order.ref_code) <> '' then

    -- Requirement 23.1. Trimmed lookup so stray whitespace captured with the
    -- link cannot silently cost a referrer their credit. Case is NOT folded:
    -- ref_code is generated over an upper-case alphabet and is unique, so
    -- exact-code matching is the specified behaviour.
    select * into v_referrer
    from public.profiles
    where ref_code = btrim(v_order.ref_code);

    if not found then
      -- Requirement 23.4: unknown code, zero referral rows, enrollment stands.
      null;

    elsif v_referrer.id = v_order.user_id then
      -- Requirement 23.3: self-referral. Zero referral rows (the
      -- referrals_no_self constraint would refuse one anyway) and the attempt
      -- is recorded against the order for admin review.
      insert into public.payment_incidents
        (kind, order_id, hitpay_payment_id, payload)
      values ('self_referral', v_order.id, p_payment_id, p_payload);

    else
      -- Referral configuration is read from settings with the definer's
      -- privileges (Requirement 24.3). Every read falls back to the seeded
      -- default when the row is absent OR unusable (Requirement 24.4): a bad
      -- value must not raise, because a raise here would roll back a payment
      -- that has already been taken and make HitPay retry it forever.
      select value into v_setting from public.settings where key = 'reward_on';
      v_reward_on := lower(btrim(coalesce(v_setting, '')));
      if v_reward_on = '' then
        v_reward_on := 'every_purchase';
      end if;

      -- Requirement 23.6. The current order is already 'paid' by step 6, so it
      -- must be excluded; created_at scopes the test to a PRECEDING paid order.
      if v_reward_on = 'first_purchase_only'
         and exists (
           select 1
           from public.orders o
           where o.user_id = v_order.user_id
             and o.status  = 'paid'
             and o.id     <> v_order.id
             and o.created_at <= v_order.created_at
         ) then
        null;

      else
        -- Requirement 23.7 for 'every_purchase', and for any unrecognised
        -- reward_on value, which falls back to the seeded default behaviour.
        select value into v_setting
          from public.settings where key = 'referral_amount';
        v_setting := btrim(coalesce(v_setting, ''));
        if v_setting ~ '^[0-9]{1,10}(\.[0-9]+)?$' then
          v_reward_amt := round(v_setting::numeric, 2);
        else
          v_reward_amt := 9;                       -- seeded default (24.1, 24.4)
        end if;

        select value into v_setting
          from public.settings where key = 'reward_type';
        v_setting := lower(btrim(coalesce(v_setting, '')));
        if v_setting in ('cash', 'credit') then
          v_reward_ty := v_setting::public.reward_type;
        else
          v_reward_ty := 'cash';                   -- seeded default (24.1, 24.4)
        end if;

        -- Requirement 7.7: the buyer's identity is masked once, here, so
        -- buyer_user_id can stay outside the client grant entirely.
        v_mask := public.mask_email(
                    (select email from public.profiles where id = v_order.user_id));

        -- Denormalised so the ledger still renders after the product is
        -- unpublished. products.title is not null and the order's FK
        -- guarantees the row exists.
        select title into v_title
          from public.products where id = v_order.product_id;

        insert into public.referrals
          (referrer_ref_code, referrer_user_id, buyer_user_id, buyer_masked,
           order_id, product_id, product_title, amount_php, reward_type, status)
        values
          (v_referrer.ref_code, v_referrer.id, v_order.user_id,
           coalesce(v_mask, '***'),
           v_order.id, v_order.product_id, coalesce(v_title, 'Product'),
           v_reward_amt, v_reward_ty, 'available')
        on conflict (order_id) do nothing;   -- Requirements 23.5, 16.4
      end if;
    end if;
  end if;

  return jsonb_build_object('outcome', 'fulfilled', 'order_id', v_order.id);
end $$;

comment on function public.fulfil_payment(text, numeric, text, jsonb) is
  'Requirements 15, 16, 23, 24. One transaction: lock the order, cross-check the reported amount and currency against the stored values at two decimals with zero tolerance, mark paid, grant the enrollment, attribute the referral. Replays return at the already-paid branch with paid_at untouched. Every non-fulfilment branch returns normally so the incident row commits and the webhook can answer HTTP 200; a genuine fault raises and rolls back the whole body. Service role only.';

-- ---------------------------------------------------------------------------
-- Privileges (Requirement 8.4)
-- ---------------------------------------------------------------------------
-- PUBLIC is revoked as well as anon and authenticated. A new function's EXECUTE
-- is granted to PUBLIC by default, and both client roles inherit through it, so
-- revoking the two named roles alone would leave this function callable from a
-- browser as `POST /rest/v1/rpc/fulfil_payment`. 0005 already set the default
-- privileges that close this; these statements are the explicit belt.

revoke all on function public.fulfil_payment(text, numeric, text, jsonb) from public;
revoke all on function public.fulfil_payment(text, numeric, text, jsonb) from anon;
revoke all on function public.fulfil_payment(text, numeric, text, jsonb) from authenticated;

grant execute on function public.fulfil_payment(text, numeric, text, jsonb) to service_role;

-- =======================================================================
-- 0012_fn_refund_fail_payment.sql
-- =======================================================================
-- 0012_fn_refund_fail_payment.sql
-- Platform v2 reversal and failure paths:
--   public.refund_payment(text, numeric, text, jsonb)
--   public.fail_payment(text, numeric, text, jsonb)
--
-- Both functions are the mirror image of 0011's fulfilment: one function body,
-- therefore ONE transaction, so the order status change, the enrollment
-- revocation and the referral void either all commit or all roll back
-- (Requirement 17.12). supabase-js issues each statement as its own transaction
-- over PostgREST, so this cannot be assembled correctly in Deno; the
-- hitpay-webhook Edge Function verifies the HMAC, normalises the payload, and
-- hands the whole decision to one of these RPCs.
--
-- Depends on:
--   0001  enum types order_status, referral_status, incident_kind
--   0002  orders (partial unique index on hitpay_payment_id), enrollments
--         (enrollments_user_product_key), referrals (unique order_id),
--         payment_incidents
--   0005  the revoke-first baseline and FORCE RLS on orders/enrollments/
--         referrals
--   0011  fulfil_payment, whose conventions these two follow exactly
--
-- Privileges: SECURITY DEFINER, owned by the migration role (postgres), EXECUTE
-- granted to service_role only (Requirement 8.4). 0005 already flipped default
-- privileges so these functions arrive closed to anon, authenticated and
-- PUBLIC; the revokes at the bottom are stated explicitly anyway, because
-- PostgREST exposes every public-schema function as an RPC endpoint and these
-- two delete access rows and cancel rewards.
--
-- RLS note: orders, enrollments and referrals are FORCE ROW LEVEL SECURITY with
-- zero policies, so these bodies work because the owner role holds BYPASSRLS on
-- Supabase (the deploy-time check is stated in 0005). If the owner lacked it,
-- the writes would fail closed and roll back the whole reversal rather than
-- half-applying it.
--
-- search_path note: pinned to `public, pg_temp` with pg_temp LAST, so a caller
-- cannot redirect these definer functions at a shadowed table and a temp object
-- cannot shadow a public one. pg_catalog is searched first implicitly, so the
-- built-ins used here (round, abs, concat_ws) cannot be shadowed either.
--
-- Signature note: the reported amount and currency carry defaults, because a
-- refund is accepted for ANY reported amount (Requirement 17.1) and a failure
-- reports no amount at all, so neither value is needed to make the decision.
-- They are accepted so the reported figures can be retained on an incident row
-- (Requirement 15.8) when the payment identifier matches no order. The webhook
-- may therefore call either shape by name:
--   rpc('refund_payment', { p_payment_id, p_payload })
--   rpc('refund_payment', { p_payment_id, p_reported_amount,
--                           p_reported_currency, p_payload })
--
-- Requirements: 17.1, 17.2, 17.4, 17.5, 17.7, 17.8, 17.10, 17.11, 17.12,
--               16.8, 16.9, 15.8, 8.4

-- ---------------------------------------------------------------------------
-- refund_payment
-- ---------------------------------------------------------------------------

create or replace function public.refund_payment(
  p_payment_id        text,
  p_reported_amount   numeric default null,
  p_reported_currency text    default null,
  p_payload           jsonb   default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order public.orders;
  v_round numeric;               -- unconstrained: an absurd payload value must
  v_fit   numeric(12,2);         -- not overflow before it is recorded
begin
  -- (0) Narrow the reported amount for storage BEFORE anything else. There is
  --     no amount cross-check on a refund (Requirement 17.1), so this value
  --     never influences the decision; it only has to be storable in
  --     payment_incidents.reported_amount, which is numeric(12,2). An absurd
  --     payload figure must land as a null reported amount on an incident row,
  --     not raise a numeric overflow that would roll back the incident and make
  --     HitPay retry a call that can never succeed. The full payload is stored
  --     either way, so nothing is lost when v_fit is null.
  --
  --     abs() of Infinity fails the bound, so infinities narrow to null too,
  --     and the bound is re-tested AFTER rounding because a value just under
  --     10^10 can round up past what numeric(12,2) holds.
  v_fit := null;
  if p_reported_amount is not null
     and p_reported_amount <> 'NaN'::numeric
     and abs(p_reported_amount) < 10000000000 then
    v_round := round(p_reported_amount, 2);
    if abs(v_round) < 10000000000 then
      v_fit := v_round;
    end if;
  end if;

  -- (1) Resolve the order and LOCK it. The lock is what makes repeated and
  --     concurrent refund deliveries safe (Requirement 17.7): the second call
  --     resumes only after the first commits, then re-reads the row under READ
  --     COMMITTED and sees status = 'refunded'. The partial unique index on
  --     hitpay_payment_id guarantees at most one matching row.
  select * into v_order
  from public.orders
  where hitpay_payment_id = p_payment_id
  for update;

  -- (2) Refund for an unknown payment identifier (Requirement 17.8). Zero
  --     writes to orders, enrollments and referrals; the incident is the only
  --     row added, and it commits so the webhook can answer HTTP 200. The
  --     reported amount and currency are retained on it (Requirement 15.8).
  if not found then
    insert into public.payment_incidents
      (kind, hitpay_payment_id, reported_amount, reported_currency, payload)
    values ('unmatched_refund', p_payment_id, v_fit, p_reported_currency,
            p_payload);
    return jsonb_build_object('outcome', 'unmatched_refund');
  end if;

  -- (3) Repeat delivery for an already-refunded order (Requirement 17.7).
  --     Return BEFORE touching anything: the order row, the enrollment row
  --     count for that user and product, and the referral's status AND note all
  --     have to be exactly what the first refund left behind. Re-running the
  --     referral update would satisfy the status assertion and still violate
  --     17.7, because concat_ws would append the void note a second time.
  if v_order.status = 'refunded' then
    return jsonb_build_object('outcome', 'already_refunded',
                              'order_id', v_order.id);
  end if;

  -- (4) Requirement 17.1: the status change applies for ANY reported refunded
  --     amount, partial or full, because a partial refund still reverses the
  --     purchase. There is deliberately no amount comparison here, unlike
  --     fulfilment in 0011.
  --
  --     paid_at is left exactly as it was. The order row is retained as the
  --     financial record of a purchase that happened and was then reversed
  --     (Requirement 17.2), so erasing when it was paid would destroy audit
  --     history.
  update public.orders
     set status = 'refunded'
   where id = v_order.id;

  -- (5) Revoke access (Requirement 17.2). Scoped to THIS order's user and
  --     product, never a blanket delete, so every other enrollment held by that
  --     user survives untouched. enrollments_user_product_key means this
  --     matches at most one row.
  --
  --     Scoping deliberately stops at (user_id, product_id) and does NOT also
  --     require order_id = this order: Requirement 17.13 asserts ZERO
  --     enrollments rows for that pair after the refund, and Requirement 17.3
  --     requires the 403 to hold for every later request. An enrollment for the
  --     same pair carrying a different order_id (or a null one from a comp
  --     grant) would otherwise survive and keep the content unlocked after the
  --     money was returned.
  --
  --     Zero rows deleted is not an error (Requirement 17.10): an order with no
  --     enrollment still becomes refunded and still returns HTTP 200.
  --
  --     quiz_attempts is NOT touched. Requirement 17.2 preserves the affected
  --     user's attempt history across a refund; the 403 comes from the missing
  --     enrollment, not from erased history.
  delete from public.enrollments
   where user_id    = v_order.user_id
     and product_id = v_order.product_id;

  -- (6) Void the referral (Requirements 17.4, 17.5, 17.11).
  --
  --     status and notes on the right-hand side read the OLD row, which is what
  --     lets one statement cover both cases: an 'available' reward is simply
  --     cancelled, and a reward already paid out is cancelled WITH a note
  --     saying the money has already left, appended to whatever note was there
  --     before. concat_ws skips a null note, so a first note is not prefixed
  --     with a separator.
  --
  --     paid_at is not in the SET list, so the recorded payout timestamp
  --     survives untouched (Requirement 17.5). The platform really did send
  --     that money; the row has to keep saying so even though it is now void.
  --
  --     Requirement 17.11: zero matching rows is not an error, and zero
  --     referrals rows are ever created here.
  update public.referrals
     set status = 'void',
         notes  = concat_ws(' | ', notes,
                    case when status = 'paid'
                      then 'Voided after refund; reward had already been paid out.'
                      else 'Voided after refund.' end)
   where order_id = v_order.id;

  return jsonb_build_object('outcome', 'refunded', 'order_id', v_order.id);
end $$;

comment on function public.refund_payment(text, numeric, text, jsonb) is
  'Requirement 17. One transaction: lock the order, set status refunded for any reported refunded amount, delete the enrollment for that order''s user and product, void that order''s referral preserving paid_at and appending the already-paid note. Repeat deliveries return at the already-refunded branch with the order, enrollment count, referral status and referral note untouched. An unknown payment identifier records an unmatched_refund incident and writes nothing else. Every settled branch returns normally so the incident commits and the webhook answers HTTP 200; a genuine fault raises and rolls the whole reversal back together. Service role only.';

-- ---------------------------------------------------------------------------
-- fail_payment
-- ---------------------------------------------------------------------------

create or replace function public.fail_payment(
  p_payment_id        text,
  p_reported_amount   numeric default null,
  p_reported_currency text    default null,
  p_payload           jsonb   default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order public.orders;
  v_round numeric;
  v_fit   numeric(12,2);
begin
  -- (0) Same defensive narrowing as above. A failure payload usually reports no
  --     amount at all, which narrows to null and is stored as null.
  v_fit := null;
  if p_reported_amount is not null
     and p_reported_amount <> 'NaN'::numeric
     and abs(p_reported_amount) < 10000000000 then
    v_round := round(p_reported_amount, 2);
    if abs(v_round) < 10000000000 then
      v_fit := v_round;
    end if;
  end if;

  -- (1) Resolve and LOCK, so a failure report racing a completed-payment
  --     delivery for the same identifier cannot interleave with fulfilment.
  --     Whichever call takes the lock first decides; the second re-reads the
  --     committed status and lands on the matching branch below.
  select * into v_order
  from public.orders
  where hitpay_payment_id = p_payment_id
  for update;

  -- (2) Unknown payment identifier: zero writes to orders, enrollments and
  --     referrals, one incident row, HTTP 200 (Requirement 16.10 in spirit,
  --     recorded the same way fulfilment records it).
  if not found then
    insert into public.payment_incidents
      (kind, hitpay_payment_id, reported_amount, reported_currency, payload)
    values ('unmatched_payment', p_payment_id, v_fit, p_reported_currency,
            p_payload);
    return jsonb_build_object('outcome', 'unmatched');
  end if;

  -- (3) Requirement 16.9: a failed or cancelled payment reported against an
  --     order that is already paid is out of order. The order status, the
  --     enrollment and the referral are left ENTIRELY unchanged - the status is
  --     never downgraded from paid, because that would silently strip a buyer
  --     of access on the strength of a late or misrouted event. The incident is
  --     the only row written, and it commits so the webhook answers 200.
  if v_order.status = 'paid' then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('out_of_order_status', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency,
            p_payload);
    return jsonb_build_object('outcome', 'already_paid',
                              'order_id', v_order.id);
  end if;

  -- (4) Requirement 16.9, refunded arm. Same treatment: record it, change
  --     nothing. A refunded order must not be rewritten to failed, or the
  --     reversal audit trail would be lost.
  if v_order.status = 'refunded' then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('out_of_order_status', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency,
            p_payload);
    return jsonb_build_object('outcome', 'already_refunded',
                              'order_id', v_order.id);
  end if;

  -- (5) Repeat delivery of the same failure. Requirement 16.9 names only paid
  --     and refunded as out of order, so a second failure report for an
  --     already-failed order is a plain replay: no incident, no write, HTTP
  --     200.
  if v_order.status = 'failed' then
    return jsonb_build_object('outcome', 'already_failed',
                              'order_id', v_order.id);
  end if;

  -- (6) Requirement 16.8: the order was pending, so it moves to failed. Zero
  --     enrollments rows and zero referrals rows are created - there is no
  --     insert in this branch at all, which is the strongest form of that
  --     guarantee. paid_at stays null, because nothing was ever paid.
  update public.orders
     set status = 'failed'
   where id = v_order.id;

  return jsonb_build_object('outcome', 'failed', 'order_id', v_order.id);
end $$;

comment on function public.fail_payment(text, numeric, text, jsonb) is
  'Requirements 16.8, 16.9. One transaction: lock the order, move a pending order to failed granting nothing, and for an order already paid or refunded change nothing at all while recording an out_of_order_status incident for admin review. A repeated failure report for an already-failed order writes nothing. An unknown payment identifier records an unmatched_payment incident. Every settled branch returns normally so the incident commits and the webhook answers HTTP 200. Service role only.';

-- ---------------------------------------------------------------------------
-- Privileges (Requirement 8.4)
-- ---------------------------------------------------------------------------
-- PUBLIC is revoked as well as anon and authenticated. A new function's EXECUTE
-- is granted to PUBLIC by default and both client roles inherit through it, so
-- revoking the two named roles alone would leave these callable from a browser
-- as `POST /rest/v1/rpc/refund_payment`. 0005 already set the default
-- privileges that close this; these statements are the explicit belt. A client
-- reaching refund_payment could delete another user's enrollment, which is why
-- it is stated rather than assumed.

revoke all on function public.refund_payment(text, numeric, text, jsonb) from public;
revoke all on function public.refund_payment(text, numeric, text, jsonb) from anon;
revoke all on function public.refund_payment(text, numeric, text, jsonb) from authenticated;

revoke all on function public.fail_payment(text, numeric, text, jsonb) from public;
revoke all on function public.fail_payment(text, numeric, text, jsonb) from anon;
revoke all on function public.fail_payment(text, numeric, text, jsonb) from authenticated;

grant execute on function public.refund_payment(text, numeric, text, jsonb) to service_role;
grant execute on function public.fail_payment(text, numeric, text, jsonb) to service_role;

-- =======================================================================
-- Backfill: profiles for auth users created before the signup trigger
-- =======================================================================
insert into public.profiles (id, email, ref_code, is_admin)
select u.id, u.email, public.gen_ref_code(),
       exists (select 1 from public.admin_bootstrap_emails b where b.email = lower(u.email))
  from auth.users u
on conflict (id) do nothing;

commit;

select 'all 12 migrations applied' as result,
       (select count(*) from public.profiles) as profiles,
       (select count(*) from public.profiles where is_admin) as admins;
